function FugitiveWorkspace({actor,workspaceId,headingRef}:Props){
  const [register,setRegister]=useState<M77Register|null>(null),[mode,setMode]=useState<'source'|'population'>('population'),[streamId,setStreamId]=useState(''),[versionId,setVersionId]=useState('')
