  useEffect(()=>{active.current=true;void(async()=>{try{if(workspaceId){await load();if(valid())setMessage('Compare the physical equipment list with source workpapers. Unknown or unsupported equipment remains a gap.')}else setMessage('No company workspace is assigned.')}catch(e){if(valid()){setError(true);setMessage(e instanceof Error?e.message:'Records unavailable.')}}finally{if(valid())setBusy(false)}})();return()=>{active.current=false}},[]) // Actor/company changes remount this component.
  async function action(kind:string,payload:unknown,work:(key:string)=>Promise<void>){if(!valid()||lock.current)return;lock.current=true;setBusy(true);setError(false);setMessage('Verifying the requested operation…');const signature=m77CanonicalJson({kind,payload});if(attempt.current?.signature!==signature)attempt.current={signature,key:crypto.randomUUID()};try{await work(attempt.current.key);if(valid())attempt.current=null}catch(e){if(valid()){setError(true);setMessage(e instanceof Error?e.message:'The operation could not be verified. Refresh before continuing.')}}finally{if(valid()){lock.current=false;setBusy(false)}}}
