  function start(){if(!manager||busy||!register)return;reset();setEditing(true);if(mode==='population')setDeclaration(structuredClone(register.population.versions[register.population.versions.length-1]?.activity.declaration??blankPopulation()));else if(latest?.family==='source'){const draft=structuredClone(latest.activity),current=register.sources.find(s=>s.binding.sourceId===draft.binding.sourceId);if(current)draft.binding=current.binding;setSource(draft)}setMessage('Unsaved draft using current corporate coverage where the source is still available. Check the source binding. Saving adds a version; previous records remain retained.')}
