  async function save(){if(!register?.coverageVersion||!workspaceId)return;const predecessor={expectedVersionId:latest?.id??null,expectedVersionSha256:latest?.versionSha256??null,correctionReason:latest?reason:null};const input=mode==='source'&&source?{...source,...predecessor}:{profile:M77_POPULATION_PROFILE,coverageVersionId:register.coverageVersion.id,coverageVersionSha256:register.coverageVersion.versionSha256,declaration,expectedDependencySha256:register.reconciliation.dependencySha256,...predecessor};if(mode==='source'&&!source)return;
    try{const candidate={...input,idempotencyKey:crypto.randomUUID()};if(mode==='source')validateM77SourceSave(candidate);else validateM77PopulationSave(candidate)}catch(e){setError(true);setMessage(e instanceof Error?e.message:'Check required source and evidence fields. Nothing was saved.');return}
    await action('save',input,async key=>{const version=await fugitiveSaveRequest(actor,workspaceId,mode,latest?.streamId??null,{...input,idempotencyKey:key});await load(version);if(valid())setMessage('Version saved. Separate internal review remains required; corporate Scope 1 remains incomplete.')})
  }
  async function review(){if(!workspaceId||!register||!latest)return;const input:Omit<M77ReviewInput,'idempotencyKey'>={versionId:latest.id,expectedVersionSha256:latest.versionSha256,expectedDependencySha256:mode==='population'?register.reconciliation.dependencySha256:null,decision:decision==='changes'?'changes_requested':mode==='source'?'accepted_bounded_internal':'accepted_bounded_reconciliation',note:reviewNote,acknowledgedLimitations:ack?[...M77_LIMITATIONS]:[]};await action('review',input,async key=>{await fugitiveReviewRequest(actor,workspaceId,mode,latest.streamId,{...input,idempotencyKey:key});await load(latest);if(valid())setMessage('The separate review decision was saved for this exact version.')})}
