  return <section className="stationary-workspace controlled-stationary"><h2 ref={headingRef} tabIndex={-1}>Refrigerants and fire suppression</h2><p>Candidate workpapers and physical-equipment coverage · synthetic demonstration · Scope 1 incomplete</p>
    <p role={error?'alert':'status'} aria-live="polite">{message}</p>
    <nav className="worksheet-nav" aria-label="Fugitive workpaper views"><button disabled={busy} aria-pressed={mode==='population'} onClick={()=>changeMode('population')}>Equipment reconciliation</button><button disabled={busy} aria-pressed={mode==='source'} onClick={()=>changeMode('source')}>Source workpapers</button><button disabled={busy} onClick={()=>void action('refresh',{},async()=>{await load();if(valid())setMessage('Current evidence and dependencies refreshed.')})}>Refresh records</button></nav>
    {register&&<><h3>Current coverage findings</h3><p>{register.reconciliation.assets.length} declared devices · {register.reconciliation.sourceIds.length} corporate fugitive sources · {register.worksheets.length} workpapers</p>{register.reconciliation.findings.length?<ul>{register.reconciliation.findings.map((f,i)=><li key={i}>{f.assetId?`${f.assetId}: `:''}{f.message}</li>)}</ul>:<p>The declared supported population reconciles. This is not complete corporate Scope 1 or external assurance.</p>}
      {mode==='source'&&<label>Saved source workpaper<select disabled={busy||editing} value={streamId} onChange={e=>{setStreamId(e.target.value);setVersionId('');reset()}}><option value="">New source workpaper</option>{register.worksheets.map(w=><option key={w.worksheetId} value={w.worksheetId}>{w.versions[w.versions.length-1]?.activity.label??w.assetId}</option>)}</select></label>}
      {versions.length>0&&<label>Saved version<select disabled={busy||editing} value={selected?.id??''} onChange={e=>{setVersionId(e.target.value);setOpenReport(null)}}>{versions.map(v=><option key={v.id} value={v.id}>Version {v.version} — {v.review?.decision.replace(/_/g,' ')??'unreviewed'}</option>)}</select></label>}
      {selected&&!editing&&<><h3>{selected.family==='source'?selected.activity.label:'Physical population'} · version {selected.version}</h3><p>{selected.review?.decision.replace(/_/g,' ')??'No review saved'} · {new Date(selected.createdAt).toLocaleString()}</p>{selected.findings.length>0&&<ul>{selected.findings.map((f,i)=><li key={i}>{f.message}</li>)}</ul>}{selected.family==='source'&&selected.calculation&&<><h3>{selected.calculation.kg_co2e_display} kg CO₂e</h3><p>{selected.calculation.estimated_emitted_kg} kg estimated {selected.calculation.gas} emissions · GWP {selected.calculation.gwp}</p><p>Candidate servicing-based estimate. Statement retention does not authenticate an original record.</p></>}</>}
      {manager&&!editing&&<button disabled={busy||!register.coverageVersion} onClick={start}>{latest?'Prepare correction of latest version':mode==='source'?'Prepare source workpaper':'Declare equipment population'}</button>}
      {editing&&<><fieldset disabled={busy}>{mode==='source'?<><label>Corporate fugitive source<select value={source?.binding.sourceId??''} onChange={e=>chooseSource(e.target.value)}><option value="">Select source</option>{register.sources.map(s=><option key={s.binding.sourceId} value={s.binding.sourceId}>{s.sourceLabel} — {s.facilityLabel}{s.eligible?'':' — unsupported boundary'}</option>)}</select></label>{source&&<FugitiveSourceEditor value={source} onChange={setSource} disabled={busy}/>}</>:<FugitivePopulationEditor value={declaration} register={register} onChange={setDeclaration} disabled={busy}/>}{latest&&<label>Why this version is being corrected<textarea value={reason} onChange={e=>setReason(e.target.value)}/></label>}<button onClick={()=>void save()} disabled={busy||mode==='source'&&!source}>Save new version</button><button onClick={reset}>Discard unsaved draft</button></fieldset></>}
      {manager&&latest&&!editing&&selected?.id===latest.id&&<fieldset disabled={busy}><legend>Separate internal review</legend><p>A manager who contributed to this workpaper cannot approve it. The server checks reviewer eligibility and current evidence.</p><label>Decision<select value={decision} onChange={e=>setDecision(e.target.value as 'accept'|'changes')}><option value="changes">Request changes</option><option value="accept">Accept this bounded workpaper</option></select></label><label>Review explanation<textarea value={reviewNote} onChange={e=>setReviewNote(e.target.value)}/></label><label className="stationary-check"><input type="checkbox" checked={ack} onChange={e=>setAck(e.target.checked)}/>I acknowledge the synthetic data, unreleased method, incomplete Scope 1 and corporate inventory, unresolved legal requirements, no emissions aggregation and no external assurance.</label><button disabled={!ack||!reviewNote.trim()} onClick={()=>void review()}>Save separate review</button></fieldset>}
