export function buildM77Dependencies(coverage:M71Version|null,workpapers:M77SourceVersion[],hash:(v:unknown)=>string):M77Dependencies{const b={coveragePin:coverage?{id:coverage.id,sha256:coverage.versionSha256}:null,coverageReviewPin:coverage?.review?{id:coverage.review.id,sha256:coverage.review.decisionSha256}:null,workpaperPins:[...workpapers].sort((a,b)=>a.streamId.localeCompare(b.streamId)).map(w=>({worksheetId:w.streamId,sourceId:w.activity.binding.sourceId,assetId:w.activity.assetId,version:{id:w.id,sha256:w.versionSha256},decision:w.review?{id:w.review.id,sha256:w.review.decisionSha256}:null}))};return {...b,dependencySha256:hash(b)}}
