 const dependencies=buildM77Dependencies(coverage,workpapers,hash),d=population?.activity.declaration??null,findings:M77Finding[]=[],add=(code:string,message:string,assetId:string|null=null,sourceId:string|null=null)=>findings.push({code,message,blocking:true,assetId,sourceId});if(!coverage)add('coverage_missing','Corporate coverage is missing.');if(!coverage?.review||coverage.review.decision!=='accepted_bounded_internal')add('coverage_review_required','Corporate coverage requires separate internal review.');if(!population)add('population_missing','Independent physical fugitive population has not been declared.');if(population&&(population.activity.coverageVersionId!==coverage?.id||population.activity.coverageVersionSha256!==coverage?.versionSha256))add('stale_coverage','Population is bound to an earlier corporate boundary.');if(population&&population.dependencies?.dependencySha256!==dependencies.dependencySha256)add('stale_dependencies','Rebind the population to current source workpapers and reviews.');if(!d)add('declaration_missing','Independent discovery statement is missing.');if(d){if(d.completeness!=='declared_complete'||!d.allControlledLocationsIncluded||!d.controlledFleetChecked||!d.assets.length)add('discovery_incomplete','Discovery must explicitly cover the full controlled physical population and fleet.');for(const e of coverage?.snapshot.entities??[])if(!d.coveredEntityIds.includes(e.id))add('entity_omitted','A corporate entity is absent from discovery.');for(const f of coverage?.snapshot.facilities??[])if(!d.coveredFacilityIds.includes(f.id))add('facility_omitted','A corporate facility is absent from discovery.');for(const id of d.coveredEntityIds)if(!coverage?.snapshot.entities.some(e=>e.id===id))add('unknown_entity','Discovery includes an unknown corporate entity.');for(const id of d.coveredFacilityIds)if(!coverage?.snapshot.facilities.some(f=>f.id===id))add('unknown_facility','Discovery includes an unknown corporate facility.')}
 const assets=d?.assets??[],sources=coverage?.snapshot.sources.filter(s=>s.domain==='fugitive')??[];for(const a of assets){if(assets.filter(x=>x.assetId===a.assetId).length>1)add('duplicate_asset','Physical device identity is duplicated.',a.assetId,a.sourceId);if(!coverage?.snapshot.entities.some(e=>e.id===a.entityId)||a.facilityId!==null&&!coverage?.snapshot.facilities.some(f=>f.id===a.facilityId&&f.entityId===a.entityId))add('unknown_asset_location','Physical asset location is unresolved.',a.assetId,a.sourceId);const src=sources.find(s=>s.id===a.sourceId);if(!src)add('unmatched_asset','Physical asset has no corporate fugitive source.',a.assetId,a.sourceId);else if(src.entityId!==a.entityId||src.facilityId!==a.facilityId)add('asset_source_mismatch','Physical and corporate source locations conflict.',a.assetId,a.sourceId);if(a.sourceId&&assets.filter(x=>x.sourceId===a.sourceId).length>1)add('duplicate_source_mapping','Multiple devices share one corporate source.',a.assetId,a.sourceId);if(!a.gas||!(Object.prototype.hasOwnProperty.call(gasFactors,a.gas)?gasFactors[a.gas]:undefined)?.equipment.includes(a.equipment)||!a.capacityKg||mass(a.capacityKg)<=0n||a.controlBasis!=='owned_operational_control_full_year')add('unsupported_asset','Gas, equipment, charge or operational control is unsupported.',a.assetId,a.sourceId);const ws=workpapers.filter(w=>w.activity.assetId===a.assetId&&w.activity.binding.sourceId===a.sourceId);if(ws.length!==1)add('workpaper_missing_or_duplicate','Physical device requires exactly one effective workpaper.',a.assetId,a.sourceId);for(const w of ws){if(w.activity.binding.entityId!==a.entityId||w.activity.binding.facilityId!==a.facilityId||w.activity.gas!==a.gas||w.activity.equipment!==a.equipment||w.activity.capacityKg!==a.capacityKg)add('workpaper_asset_mismatch','Workpaper and physical device facts conflict.',a.assetId,a.sourceId);if(w.activity.binding.coverageVersionId!==coverage?.id||w.activity.binding.coverageVersionSha256!==coverage?.versionS