 const review=population?reviews.find(r=>r.versionId===population.id&&r.dependencies?.dependencySha256===dependencies.dependencySha256)??null:null;if(review?.decision!=='accepted_bounded_reconciliation')add('population_review_required','Exact population reconciliation requires separate internal review.');const b={companyId,dependencies,dependencySha256:dependencies.dependencySha256,populationVersionPin:population?{id:population.id,sha256:population.versionSha256}:null,reviewPin:review?{id:review.id,sha256:review.decisionSha256}:null,status:findings.length?'blocked' as const:'reconciled_bounded_synthetic' as const,findings,assets,sourceIds:sources.map(s=>s.id),worksheetIds:workpapers.map(w=>w.streamId).sort(),emissionsTotals:null,scope1Completeness:'incomplete' as const,corporateCompleteness:'incomplete' as const,releaseEligible:false as const,assurance:'none' as const,limitations:[...M77_LIMITATIONS]};return {...b,contentSha256:hash(b)}
}


function m77ControlChain(v:M71Version,entityId:string):boolean{const seen=new Set<string>();let node=entityId;while(node){if(seen.has(node))return false;seen.add(node);const rel=v.snapshot.relationships.find(r=>r.childEntityId===node);if(!rel)return true;if(rel.start!=="2025-01-01"||rel.endExclusive!=="2026-01-01"||rel.ownershipPercent!=="100"||!rel.controlFacts||!rel.evidenceRefs.length)return false;node=rel.parentEntityId}return true}

export function parseM77Json(text:string,maxBytes=250000):unknown{if(!Number.isInteger(maxBytes)||maxBytes<1||maxBytes>10000000||new TextEncoder().encode(text).length>maxBytes)fail("Fugitive response exceeds capacity.");let i=0;const ws=()=>{while(/\s/.test(text[i]??"")&&i<text.length)i++};const str=()=>{const start=i++;while(i<text.length){if(text[i]==="\\"){i+=2;continue}if(text[i++]==='"')return JSON.parse(text.slice(start,i)) as string}return fail("Invalid fugitive JSON.")};const scan=()=>{ws();if(text[i]==="{"){i++;const keys=new Set<string>();ws();if(text[i]==="}"){i++;return}while(i<text.length){ws();if(text[i]!=='"')fail("Invalid fugitive JSON.");const key=str();if(keys.has(key))fail("Duplicate JSON keys are not accepted.");keys.add(key);ws();if(text[i++]!==":")fail("Invalid fugitive JSON.");scan();ws();const end=text[i++];if(end==="}")return;if(end!==",")fail("Invalid fugitive JSON.")}}else if(text[i]==="["){i++;ws();if(text[i]==="]"){i++;return}while(i<text.length){scan();ws();const end=text[i++];if(end==="]")return;if(end!==",")fail("Invalid fugitive JSON.")}}else if(text[i]==='"'){str()}else{const start=i;while(i<text.length&&!/[\s,}\]]/.test(text[i]!))i++;if(start===i)fail("Invalid fugitive JSON.");JSON.parse(text.slice(start,i))}};try{scan();ws();if(i!==text.length)fail("Invalid fugitive JSON.");return JSON.parse(text)}catch(e){if(e instanceof M77ValidationError)throw e;return fail("Invalid fugitive JSON.")}}

import type {M77ReportSnapshot} from './m77-contract'
import {m77CanonicalJson} from './m77-validation'
const escape=(v:unknown)=>String(v??'Unknown').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;')
const readable=(v:string)=>({fixed_hvac:'Fixed air conditioning',fixed_refrigeration:'Fixed refrigeration',fixed_fire_suppression:'Fixed fire suppression',portable_fire_suppression:'Portable fire suppression',mobile_hvac:'Vehicle air conditioning',mobile_refrigeration:'Refrigerated transport',owned_operational_control_full_year:'Owned and controlled throughout the year',partial_year:'Partial year — unsupported',other:'Other — unsupported',unknown:'Unknown',accepted_bounded_internal:'Accepted for this internal workpaper',accepted_bounded_reconciliation:'Accepted for this equipment reconciliation',changes_requested:'Changes requested',unreviewed:'Not reviewed'} as Record<string,string>)[v]??v
export function m77RenderReport(s:M77ReportSnapshot):string{
 const v=s.version,title=v.family==='source'?'Fugitive source workpaper':'Physical fugitive population reconciliation',status=v.family==='source'?(v.calculation?'Candidate method estimate':'Blocked — incomplete or unsupported method facts'):(s.reconciliation?.status==='reconciled_bounded_synthetic'?'Declared synthetic population reconciled':'Blocked — open reconciliation findings'),findings=s.reconciliation?.findings??v.findings;
 const number=v.family==='source'&&v.calculation?'<p>Gas '+escape(v.calculation.gas)+' · estimated emitted kg '+escape(v.calculation.estimated_emitted_kg)+' · kg CO2e '+escape(v.calculation.kg_co2e_display)+' (half-even, four decimals). Candidate AR5 GWP '+escape(v.calculation.gwp)+'. Known releases are already reconciled inside refill activity and are not added again.</p>':'';
 const statementLinks=v.statements.map(x=>'<li><a href="#evidence-'+escape(x.id)+'">'+escape(x.reference)+'</a> — '+escape(x.issuer)+' · '+escape(x.locator)+' · SHA-256 '+escape(x.sha256)+'</li>').join('');
 const evidenceSections=v.statements.map(x=>'<section id="evidence-'+escape(x.id)+'"><h3>'+escape(x.reference)+' · '+escape(x.issuer)+'</h3><p>'+escape(x.description)+'</p><details><summary>Exact retained statement</summary><pre>'+escape(x.text)+'</pre></details></section>').join('');
 const label=v.family==='source'?v.activity.label:'Independent physical discovery',company=(s.proof?.coverageVersion??v.coverageVersion).snapshot.companyLabel;
 const assetRows=(s.reconciliation?.assets??[]).map(a=>'<tr><td data-label="Asset">'+escape(a.assetId)+'</td><td data-label="Equipment">'+escape(readable(a.equipment))+'</td><td data-label="Gas">'+escape(a.gas)+'</td><td data-label="Charge kg">'+escape(a.capacityKg)+'</td><td data-label="Corporate source">'+escape((s.proof?.coverageVersion??v.coverageVersion).snapshot.sources.find(x=>x.id===a.sourceId)?.name??a.sourceId)+'</td><td data-label="Control">'+escape(readable(a.controlBasis))+'</td></tr>').join('');
 return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src \'none\'; style-src \'unsafe-inline\'; base-uri \'none\'; form-action \'none\'"><title>'+title+'</title><style>body{font:16px/1.5 system-ui;margin:2rem auto;padding:0 1rem;max-width:1000px;color:#172f2c;overflow-wrap:anywhere}table{border-collapse:collapse;width:100%}th,td{padding:.4rem;text-align:left;border-bottom:1px solid #ccd8d0}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.5 monospace;background:#f3f6f3;padding:1rem}@media(max-width:600px){thead{display:none}tr{display:block;margin:.8rem 0}td{display:block}td::before{content:attr(data-label);font-weight:600;margin-right:.5rem}}@media print{body{font-size:10pt;margin:0}tr{break-inside:avoid}}</style></head><body><h1>'+title+' — synthetic internal draft</h1><p>Company '+escape(company)+' · '+escape(label)+'</p><p>'+escape(status)+'</p><p>Calendar 2025 · version '+v.version+' · internal review: '+escape(readable(s.review?.decision??'unreviewed'))+'.</p><p>No complete Scope 1 or corporate inventory claim. Candidate methods and factors are not released. Requirements are not determined. No external assurance. No emissions aggregation.</p>'+number+'<h2>Retained evidence</h2><ul>'+statementLinks+'</ul>'+evidenceSections+'<h2>Physical devices</h2><table><thead><tr><th>Asset</th><th>Equipment</th><th>Gas</th><th>Charge kg</th><th>Corporate source</th><th>Control</th></tr></thead><tbody>'+assetRows+'</tbody></table><h2>Open findings</h2><ul>'+findings.map(f=>'<li>'+escape(f.message)+'</li>').join('')+'</ul><details><summary>Exact retained data and provenance</summary><pre>'+escape(m77CanonicalJson(s))+'</pre></details></body></html>'
}

-- M77 additive synthetic fugitive workpapers and independent physical discovery.
-- Earlier migration bytes and rows are preserved. No aggregate emissions total.
create table neuvetra.fugitive_heads(id uuid primary key,company_id uuid not null references neuvetra.companies(id),family text not null check(family in('source','population')),source_id uuid,asset_id text,year integer not null check(year=2025),version_id uuid,revision integer not null default 0,unique(id,company_id),check((family='source' and source_id is not null and asset_id is not null)or(family='population' and source_id is null and asset_id is null)));
create unique index m77_source_identity on neuvetra.fugitive_heads(company_id,year,source_id)where family='source';
create unique index m77_asset_identity on neuvetra.fugitive_heads(company_id,year,asset_id)where family='source';
create unique index m77_population_identity on neuvetra.fugitive_heads(company_id,year)where family='population';
create table neuvetra.fugitive_statements(id uuid primary key,company_id uuid not null references neuvetra.companies(id),payload jsonb not null,statement_sha256 text not null,statement_text text not null,unique(id,company_id));
create table neuvetra.fugitive_versions(id uuid primary key,company_id uuid not null,stream_id uuid not null,version integer not null,previous_version_id uuid,coverage_version_id uuid not null,payload jsonb not null,input_sha256 text not null,content_sha256 text not null,version_sha256 text not null,created_by uuid not null references auth.users(id),created_at timestamptz not null,export_text text not null,unique(id,company_id),unique(company_id,stream_id,version),foreign key(stream_id,company_id)references neuvetra.fugitive_heads(id,company_id),foreign key(previous_version_id,company_id)references neuvetra.fugitive_versions(id,company_id),foreign key(coverage_version_id,company_id)references neuvetra.corporate_inventory_versions(id,company_id));
alter table neuvetra.fugitive_heads add foreign key(version_id,company_id)references neuvetra.fugitive_versions(id,company_id);
create table neuvetra.fugitive_reviews(id uuid primary key,company_id uuid not null,version_id uuid not null,payload jsonb not null,decision_sha256 text not null,reviewed_by uuid not null references auth.users(id),reviewed_at timestamptz not null,unique(id,company_id),foreign key(version_id,company_id)references neuvetra.fugitive_versions(id,company_id));
create unique index m77_review_state on neuvetra.fugitive_reviews(company_id,version_id,coalesce((payload#>>'{dependencies,dependencySha256}'),'source'));
create table neuvetra.fugitive_reports(id uuid primary key,company_id uuid not null,stream_id uuid not null,version_id uuid not null,payload jsonb not null,report_sha256 text not null,created_by uuid not null references auth.users(id),created_at timestamptz not null,unique(id,company_id),foreign key(stream_id,company_id)references neuvetra.fugitive_heads(id,company_id),foreign key(version_id,company_id)references neuvetra.fugitive_versions(id,company_id));
create table neuvetra.fugitive_requests(company_id uuid not null references neuvetra.companies(id),idempotency_key uuid not null,actor_id uuid not null references auth.users(id),kind text not null check(kind in('save','review','report')),family text not null check(family in('source','population')),stream_id uuid,fingerprint text not null,record_id uuid not null,primary key(company_id,idempotency_key));
create table neuvetra.fugitive_audit(sequence bigserial primary key,id uuid not null unique,company_id uuid not null references neuvetra.companies(id),record_id uuid not null,kind text not null check(kind in('save','review','report')),record_sha256 text not null,actor_id uuid not null references auth.users(id),created_at timestamptz not null,unique(company_id,kind,record_id));
create table neuvetra.fugitive_event_reservations(company_id uuid not null,year integer not null check(year=2025),kind text not null check(kind in('event','contractor_reference','release_reference')),event_key text not null,stream_id uuid not null,asset_id text not null,created_at timestamptz not null,primary key(company_id,year,kind,event_key),foreign key(stream_id,company_id)references neuvetra.fugitive_heads(id,company_id));
do $$declare t text;begin foreach t in array array['fugitive_heads','fugitive_statements','fugitive_versions','fugitive_reviews','fugitive_reports','fugitive_requests','fugitive_audit','fugitive_event_reservations']loop execute format('alter table neuvetra.%I enable row level security',t);execute format('alter table neuvetra.%I force row level security',t);execute format('revoke all on neuvetra.%I from public,authenticated,neuvetra_runtime',t);execute format('create policy m77_read on neuvetra.%I for select to neuvetra_runtime using(neuvetra.has_staging_access() and neuvetra.is_company_member(company_id))',t);execute format('grant select on neuvetra.%I to neuvetra_runtime',t);if t<>'fugitive_heads'then execute format('create trigger m77_immutable before update or delete on neuvetra.%I for each row execute function neuvetra.reject_inventory_history_mutation()',t);end if;end loop;end $$;
revoke all on sequence neuvetra.fugitive_audit_sequence_seq from public,authenticated,neuvetra_runtime;

create function neuvetra.m77_lock(target_company uuid,writing boolean)returns boolean language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$begin if not neuvetra.m71_lock(target_company,writing)then return false;end if;if writing then perform id from neuvetra.companies where id=target_company for update;perform id from neuvetra.corporate_inventory_heads where company_id=target_company for update;perform id from neuvetra.fugitive_heads where company_id=target_company order by id for update;else perform id from neuvetra.companies where id=target_company for share;end if;return true;end $$;
create function neuvetra.m77_current_coverage(target_company uuid)returns jsonb language sql stable security definer set search_path=pg_catalog,neuvetra,pg_temp as $$select v.export_text::jsonb||jsonb_build_object('review',r.payload)from neuvetra.corporate_inventory_heads h join neuvetra.corporate_inventory_versions v on v.id=h.version_id and v.company_id=h.company_id left join neuvetra.corporate_inventory_reviews r on r.version_id=v.id and r.company_id=v.company_id where h.company_id=target_company$$;
create function neuvetra.m77_current_workpapers(target_company uuid)returns jsonb language sql stable security definer set search_path=pg_catalog,neuvetra,pg_temp as $$select coalesce(jsonb_agg(v.payload||jsonb_build_object('review',r.payload) order by h.id),'[]')from neuvetra.fugitive_heads h join neuvetra.fugitive_versions v on v.id=h.version_id and v.company_id=h.company_id left join neuvetra.fugitive_reviews r on r.version_id=v.id and r.company_id=v.company_id where h.company_id=target_company and h.family='source'$$;
create function neuvetra.m77_dependencies(coverage jsonb,workpapers jsonb)returns jsonb language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$with pins as(select coalesce(jsonb_agg(jsonb_build_object('worksheetId',(w->'streamId'),'sourceId',(w#>'{activity,binding,sourceId}'),'assetId',(w#>'{activity,assetId}'),'version',jsonb_build_object('id',(w->'id'),'sha256',(w->'versionSha256')),'decision',case when coalesce((w->'review'),'null'::jsonb)='null'::jsonb then 'null'::jsonb else jsonb_build_object('id',(w#>'{review,id}'),'sha256',(w#>'{review,decisionSha256}'))end)order by (w->>'streamId') collate "C"),'[]')p from jsonb_array_elements(workpapers)w),body as(select jsonb_build_object('coveragePin',case when coverage is null then 'null'::jsonb else jsonb_build_object('id',(coverage->'id'),'sha256',(coverage->'versionSha256'))end,'coverageReviewPin',case when coalesce((coverage->'review'),'null'::jsonb)='null'::jsonb then 'null'::jsonb else jsonb_build_object('id',(coverage#>'{review,id}'),'sha256',(coverage#>'{review,decisionSha256}'))end,'workpaperPins',p)b from pins)select b||jsonb_build_object('dependencySha256',neuvetra.m67_hash(b))from body$$;
create function neuvetra.m77_current_dependencies(target_company uuid)returns jsonb language sql stable security definer set search_path=pg_catalog,neuvetra,pg_temp as $$select neuvetra.m77_dependencies(neuvetra.m77_current_coverage(target_company),neuvetra.m77_current_workpapers(target_company))$$;
create function neuvetra.m77_id(v jsonb)returns void language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$begin if jsonb_typeof(v)is distinct from 'string'or (v#>>'{}')!~'^[A-Z0-9][A-Z0-9._-]{0,79}$'then raise exception 'canonical evidence/device identifier required'using errcode='22023';end if;end $$;
create function neuvetra.m77_kg(v jsonb,positive boolean default false)returns numeric language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$
#variable_conflict use_column
declare s text:=(v#>>'{}');n numeric;begin if jsonb_typeof(v)is distinct from 'string'or s!~'^(0|[1-9][0-9]{0,5})([.][0-9]{1,6})?$'then raise exception 'kg decimal string required'using errcode='22023';end if;n:=s::numeric;if positive and n<=0 then raise exception 'positive kg required'using errcode='22023';end if;return n;end $$;
create function neuvetra.m77_date(v jsonb)returns date language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$
#variable_conflict use_column
declare s text:=(v#>>'{}');d date;begin if jsonb_typeof(v)is distinct from 'string'or s!~'^2025-[0-9]{2}-[0-9]{2}$'then raise exception '2025 date required'using errcode='22023';end if;d:=s::date;if to_char(d,'YYYY-MM-DD')<>s then raise exception 'real date required'using errcode='22023';end if;return d;end $$;
create function neuvetra.m77_calculate(v jsonb)returns jsonb language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$
#variable_conflict use_column
declare k text;r jsonb;linked jsonb;ids text[]:='{}';refs text[]:='{}';release_refs text[]:='{}';total numeric:=0;gwp numeric;locator text;amount numeric;release_mass numeric;begin
perform neuvetra.m71_keys(v,'year,asset_id,gas,equipment,unit,opening_date,closing_date,opening_capacity,closing_capacity,declarations,evidence,refills,releases,zero_activity_evidence,uncertainty');if (v->'year')is distinct from '2025'::jsonb or (v->>'unit')is distinct from 'kg'or (v->>'opening_date')is distinct from '2025-01-01'or (v->>'closing_date')is distinct from '2025-12-31'or neuvetra.m77_kg((v->'opening_capacity'),true)<>neuvetra.m77_kg((v->'closing_capacity'),true)then raise exception 'unsupported year/boundary charge'using errcode='22023';end if;perform neuvetra.m77_id((v->'asset_id'));perform neuvetra.m76_diesel_text((v->'uncertainty'),2000);if length((v->>'uncertainty'))<20 then raise exception 'uncertainty required'using errcode='22023';end if;
if (v->>'gas')='R-410A'and (v->>'equipment')='fixed_hvac'then gwp:=1924;locator:='Emission Factors Hub!D575';elsif (v->>'gas')='HFC-134a'and (v->>'equipment')='fixed_refrigeration'then gwp:=1300;locator:='Emission Factors Hub!E532';elsif (v->>'gas')='HFC-227ea'and (v->>'equipment')in('fixed_fire_suppression','portable_fire_suppression')then gwp:=3350;locator:='Emission Factors Hub!E538';else raise exception 'unsupported gas/equipment'using errcode='22023';end if;
