perform neuvetra.m76_diesel_text((a->'label'),120);perform neuvetra.m77_id((a->'assetId'));if (a->>'equipment')is null or (a->>'equipment')not in('fixed_hvac','fixed_refrigeration','fixed_fire_suppression','portable_fire_suppression','mobile_hvac','mobile_refrigeration','other','unknown')then raise exception 'equipment type'using errcode='22023';end if;if (a->'gas')<>'null'::jsonb then perform neuvetra.m76_diesel_text((a->'gas'),80);end if;if (a->'capacityKg')<>'null'::jsonb then perform neuvetra.m77_kg((a->'capacityKg'));end if;if jsonb_typeof((a->'evidenceStatements'))is distinct from 'array'or jsonb_array_length((a->'evidenceStatements'))>210 then raise exception 'evidence capacity'using errcode='22023';end if;for r in select value from jsonb_array_elements((a->'evidenceStatements'))loop perform neuvetra.m71_keys(r,'reference,issuer,description');perform neuvetra.m77_id((r->'reference'));perform neuvetra.m76_diesel_text((r->'issuer'),120);perform neuvetra.m76_diesel_text((r->'description'),2000);if length((r->>'description'))<20 then raise exception 'evidence statement missing facts'using errcode='22023';end if;end loop;if(select count(distinct (x->>'reference'))from jsonb_array_elements((a->'evidenceStatements'))x)<>jsonb_array_length((a->'evidenceStatements'))then raise exception 'duplicate evidence'using errcode='22023';end if;
if (a->'calculatorInput')<>'null'::jsonb then r:=(a->'calculatorInput');perform neuvetra.m77_calculate(r);if (r->>'asset_id')is distinct from (a->>'assetId')or (r->'equipment')is distinct from (a->'equipment')or (r->'gas')is distinct from (a->'gas')or (r->'opening_capacity')is distinct from (a->'capacityKg')then raise exception 'source input facts conflict'using errcode='22023';end if;if (s->>'consolidationApproach')is distinct from 'operational_control'or (e->>'countryCode')<>'US'or (e->>'regionCode')is distinct from 'CA'or (f->>'countryCode')<>'US'or (f->>'regionCode')is distinct from 'CA'or (bd->>'disposition')<>'included_activity'or (bd->'reason')='null'::jsonb or jsonb_array_length((bd->'evidenceRefs'))=0 then raise exception 'unsupported method corporate facts'using errcode='22023';end if;if jsonb_array_length(src->'evidenceRefs')=0 or s#>>'{period,start}'<>'2025-01-01'or s#>>'{period,endExclusive}'<>'2026-01-01'or not exists(select 1 from jsonb_array_elements(s->'coverageItems')i where i->>'domain'='fugitive'and i->>'sourceId'=src->>'id'and i->>'entityId'=e->>'id'and i->>'disposition'='included_activity'and i->>'start'='2025-01-01'and i->>'endExclusive'='2026-01-01'and i->>'evidenceState'='linked'and i->>'activityDataState'in('entered','explicit_zero')and i->'reason'<>'null'::jsonb and jsonb_array_length(i->'evidenceRefs')>0)then raise exception 'source screening missing'using errcode='22023';end if;for list in select value from jsonb_array_elements(r->'refills')loop if not exists(select 1 from jsonb_array_elements(a->'evidenceStatements')st where st->'reference'=list->'reference'and st->'issuer'=list->'contractor')then raise exception 'servicing evidence contractor mismatch'using errcode='22023';end if;end loop;for list in select value from jsonb_array_elements(jsonb_build_array(e,f,src,bd))loop if (list->>'start')<>'2025-01-01'or (list->>'endExclusive')<>'2026-01-01'then raise exception 'method corporate period'using errcode='22023';end if;end loop;node:=(e->>'id');loop if node=any(seen)then raise exception 'relationship cycle'using errcode='22023';end if;seen:=array_append(seen,node);select x into rel from jsonb_array_elements((s->'relationships'))x where (x->>'childEntityId')=node;exit when rel is null;if (rel->>'start')<>'2025-01-01'or (rel->>'endExclusive')<>'2026-01-01'or (rel->>'ownershipPercent')is distinct from '100'or (rel->'controlFacts')='null'::jsonb or jsonb_array_length((rel->'evidenceRefs'))=0 then raise exception 'incomplete corporate control'using errcode='22023';end if;node:=(rel->>'parentEntityId');end loop;
for k in select (value#>>'{}')from jsonb_each((r->'evidence'))union all select (x->>'reference')from jsonb_array_elements((r->'refills'))x union all select (x->>'evidence')from jsonb_array_elements((r->'releases'))x union all select (r->>'zero_activity_evidence')where (r->'zero_activity_evidence')<>'null'::jsonb loop if not exists(select 1 from jsonb_array_elements((a->'evidenceStatements'))x where (x->>'reference')=k)then raise exception 'unresolved evidence reference'using errcode='22023';end if;end loop;end if;
else perform neuvetra.m71_keys(a,'profile,coverageVersionId,coverageVersionSha256,declaration');if (a->>'profile')is distinct from 'synthetic-fugitive-population-v1'or (a->>'coverageVersionId')is distinct from (coverage->>'id')or (a->>'coverageVersionSha256')is distinct from (coverage->>'versionSha256')then raise exception 'population binding'using errcode='22023';end if;d:=(a->'declaration');if d<>'null'::jsonb then perform neuvetra.m71_keys(d,'issuer,reference,description,discoveryBasis,completeness,coveredEntityIds,coveredFacilityIds,controlledFleetChecked,allControlledLocationsIncluded,assets');perform neuvetra.m76_diesel_text((d->'issuer'),120);perform neuvetra.m77_id((d->'reference'));perform neuvetra.m76_diesel_text((d->'description'),2000);perform neuvetra.m76_diesel_text((d->'discoveryBasis'),2000);if length((d->>'discoveryBasis'))<20 or (d->>'completeness')is null or (d->>'completeness')not in('unknown','partial','declared_complete')or jsonb_typeof((d->'controlledFleetChecked'))is distinct from 'boolean'or jsonb_typeof((d->'allControlledLocationsIncluded'))is distinct from 'boolean'then raise exception 'population discovery facts'using errcode='22023';end if;foreach k in array array['coveredEntityIds','coveredFacilityIds']loop if jsonb_typeof(d->k)is distinct from 'array'or jsonb_array_length(d->k)>25 or(select count(distinct x)from jsonb_array_elements_text(d->k)x)<>jsonb_array_length(d->k)then raise exception 'location declaration capacity/duplicates'using errcode='22023';end if;for node in select value from jsonb_array_elements_text(d->k)loop if node!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'then raise exception 'location UUID'using errcode='22023';end if;end loop;end loop;if jsonb_typeof((d->'assets'))is distinct from 'array'or jsonb_array_length((d->'assets'))>25 then raise exception 'physical population capacity'using errcode='54000';end if;for r in select value from jsonb_array_elements((d->'assets'))loop perform neuvetra.m71_keys(r,'assetId,entityId,facilityId,equipment,gas,capacityKg,controlBasis,explanation,sourceId');perform neuvetra.m77_id((r->'assetId'));if (r->>'equipment')is null or (r->>'equipment')not in('fixed_hvac','fixed_refrigeration','fixed_fire_suppression','portable_fire_suppression','mobile_hvac','mobile_refrigeration','other','unknown')or (r->>'controlBasis')is null or (r->>'controlBasis')not in('owned_operational_control_full_year','unknown','partial_year','other')then raise exception 'asset classification/control facts'using errcode='22023';end if;foreach k in array array['entityId','facilityId','sourceId']loop if r->k<>'null'::jsonb and(jsonb_typeof(r->k)is distinct from 'string'or r->>k!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')or(k='entityId'and r->k='null'::jsonb)then raise exception 'asset corporate UUID'using errcode='22023';end if;end loop;if (r->'gas')<>'null'::jsonb then perform neuvetra.m76_diesel_text((r->'gas'),80);end if;if (r->'capacityKg')<>'null'::jsonb then perform neuvetra.m77_kg((r->'capacityKg'));end if;perform neuvetra.m76_diesel_text((r->'explanation'),2000);if length((r->>'explanation'))<20 then raise exception 'asset facts explanation required'using errcode='22023';end if;end loop;end if;end if;end $$;

create function neuvetra.m77_f(code text,message text,asset text default null,source text default null)returns jsonb language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select jsonb_build_array(jsonb_build_object('code',code,'message',message,'blocking',true,'assetId',asset,'sourceId',source))$$;
create function neuvetra.m77_reconciliation(target_company uuid,coverage jsonb,workpapers jsonb,population jsonb,review jsonb)returns jsonb language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$
#variable_conflict use_column
