create function neuvetra.m77_validate_population_correction(previous jsonb,current jsonb)returns void language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$begin if exists(select 1 from jsonb_array_elements(coalesce(previous#>'{declaration,assets}','[]'::jsonb))old_asset where not exists(select 1 from jsonb_array_elements(coalesce(current#>'{declaration,assets}','[]'::jsonb))new_asset where new_asset->'assetId'=old_asset->'assetId'))then raise exception 'previously discovered physical devices cannot be removed in the bounded 2025 profile'using errcode='22023';end if;end $$;
create function neuvetra.m77_history_capacity(target_company uuid,extra integer)returns void language plpgsql stable security definer set search_path=pg_catalog,neuvetra,pg_temp as $$begin if(select coalesce(sum(octet_length(convert_to(export_text,'utf8'))),0)from neuvetra.fugitive_versions where company_id=target_company)+(select coalesce(sum(octet_length(convert_to((payload->>'html'),'utf8'))+octet_length(convert_to((payload->>'snapshotJson'),'utf8'))),0)from neuvetra.fugitive_reports where company_id=target_company)+extra>8000000 then raise exception 'fugitive retained history capacity'using errcode='54000';end if;end $$;
create function neuvetra.save_fugitive_version(target_company uuid,target_stream uuid,family text,request jsonb,p jsonb)returns uuid language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$
