perform neuvetra.m76_diesel_text((request->'note'),500);if (request->'acknowledgedLimitations')is distinct from '["synthetic_only","declared_fugitive_reconciliation_only","scope1_incomplete","corporate_inventory_incomplete","factor_and_method_not_released","no_emissions_aggregation","requirements_not_determined","no_external_assurance"]'::jsonb or (request->>'decision')is null or (request->>'decision')not in('changes_requested',case when family='source'then 'accepted_bounded_internal'else 'accepted_bounded_reconciliation'end)then raise exception 'review decision/limitations'using errcode='22023';end if;
