create function neuvetra.m77_render_report(s jsonb)returns text language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$
#variable_conflict use_column
declare v jsonb:=(s->'version');coverage jsonb:=coalesce(nullif(s#>'{proof,coverageVersion}','null'::jsonb),s#>'{version,coverageVersion}');labels jsonb:='{"fixed_hvac":"Fixed air conditioning","fixed_refrigeration":"Fixed refrigeration","fixed_fire_suppression":"Fixed fire suppression","portable_fire_suppression":"Portable fire suppression","mobile_hvac":"Vehicle air conditioning","mobile_refrigeration":"Refrigerated transport","owned_operational_control_full_year":"Owned and controlled throughout the year","partial_year":"Partial year — unsupported","other":"Other — unsupported","unknown":"Unknown","accepted_bounded_internal":"Accepted for this internal workpaper","accepted_bounded_reconciliation":"Accepted for this equipment reconciliation","changes_requested":"Changes requested","unreviewed":"Not reviewed"}'::jsonb;title text;status text;number text:='';statement_links text;asset_rows text;findings text;evidence_sections text;label text;company text;begin label:=case when (v->>'family')='source'then v#>>'{activity,label}'else 'Independent physical discovery'end;company:=coverage#>>'{snapshot,companyLabel}';title:=case when (v->>'family')='source'then 'Fugitive source workpaper'else 'Physical fugitive population reconciliation'end;status:=case when (v->>'family')='source'then case when (v->'calculation')<>'null'::jsonb then 'Candidate method estimate'else 'Blocked — incomplete or unsupported method facts'end else case when (s#>>'{reconciliation,status}')='reconciled_bounded_synthetic'then 'Declared synthetic population reconciled'else 'Blocked — open reconciliation findings'end end;
if (v->>'family')='source'and (v->'calculation')<>'null'::jsonb then number:='<p>Gas '||neuvetra.m76_html_escape((v#>>'{calculation,gas}'))||' · estimated emitted kg '||neuvetra.m76_html_escape((v#>>'{calculation,estimated_emitted_kg}'))||' · kg CO2e '||neuvetra.m76_html_escape((v#>>'{calculation,kg_co2e_display}'))||' (half-even, four decimals). Candidate AR5 GWP '||neuvetra.m76_html_escape((v#>>'{calculation,gwp}'))||'. Known releases are already reconciled inside refill activity and are not added again.</p>';end if;
select coalesce(string_agg('<li><a href="#evidence-'||neuvetra.m76_html_escape((x->>'id'))||'">'||neuvetra.m76_html_escape((x->>'reference'))||'</a> — '||neuvetra.m76_html_escape((x->>'issuer'))||' · '||neuvetra.m76_html_escape((x->>'locator'))||' · SHA-256 '||neuvetra.m76_html_escape((x->>'sha256'))||'</li>',''order by n),'')into statement_links from jsonb_array_elements((v->'statements'))with ordinality q(x,n);
select coalesce(string_agg('<section id="evidence-'||neuvetra.m76_html_escape(x->>'id')||'"><h3>'||neuvetra.m76_html_escape(x->>'reference')||' · '||neuvetra.m76_html_escape(x->>'issuer')||'</h3><p>'||neuvetra.m76_html_escape(x->>'description')||'</p><details><summary>Exact retained statement</summary><pre>'||neuvetra.m76_html_escape(x->>'text')||'</pre></details></section>',''order by n),'')into evidence_sections from jsonb_array_elements(v->'statements')with ordinality q(x,n);
