export async function createM77AuthorDatabase(name:string,baseline='m68_qa'){if(!/^m77_author_[a-z0-9_]+$/.test(name)||!['m68_qa','m63_integration','m76_author_root_ui3'].includes(baseline))throw Error('New isolated author database required.');const admin=createPostgresConnection('postgres://m63_test_admin@127.0.0.1:55463/postgres',{tls:false,maxConnections:1});let operator:WorkspaceConnection|undefined;try{if((await admin.query('select 1 from pg_database where datname=$1',[name])).rows.length)throw Error('Existing database refused.');await admin.exec(`create database ${name} template ${baseline}`);operator=createPostgresConnection(`postgres://m63_test_admin@127.0.0.1:55463/${name}`,{tls:false,maxConnections:1});const manifest=await readMigrationManifest(),receipts=(await operator.query<{name:string;sha256:string}>('select name,sha256 from neuvetra.schema_migrations order by name')).rows;if(receipts.some((r,i)=>r.name!==manifest[i]?.name||r.sha256!==manifest[i]?.sha256))throw Error('Changed baseline refused.');const preservation=await m77BaselineDigests(operator);await operator.transaction(async tx=>{for(const m of manifest.slice(receipts.length)){await tx.exec(m.sql);await tx.query('insert into neuvetra.schema_migrations(name,sha256)values($1,$2)',[m.name,m.sha256])}});const after=await m77BaselineDigests(operator,preservation.map(x=>x.table));if(JSON.stringify(preservation)!==JSON.stringify(after))throw Error('Earlier records changed during additive migration.');await Bun.write(`.superpowers/${name}-preservation.json`,JSON.stringify({status:'author_native_additive_preservation_pass',schemaBefore:receipts.length,schemaAfter:manifest.length,tables:preservation,independentReview:'pending'},null,2)+'\n');return await populateM77Fixture(operator,name)}finally{await operator?.close();await admin.close()}}
export async function serveM77Fixture(fixture:Awaited<ReturnType<typeof createM77AuthorDatabase>>,port=4187,origin='http://localhost:4186'){const runtime=createPostgresConnection(`postgres://neuvetra_runtime@127.0.0.1:55463/${fixture.name}`,{tls:false,maxConnections:5}),database=new(HostedWorkspaceDatabase as unknown as new(c:WorkspaceConnection,r:string)=>HostedWorkspaceDatabase)(runtime,fixture.projectRef),tokens=Object.fromEntries(Object.entries(fixture.users).map(([role,id])=>['synthetic-m77-'+role,id])),routes=createM77Routes({database,authority:createM77Authority(),origin,validateUser:async token=>tokens[token]?{id:tokens[token],email:undefined} as any:null});const server=Bun.serve({hostname:'127.0.0.1',port,fetch:routes});return {server,database,runtime,tokens,close:async()=>{server.stop(true);await runtime.close()}}}
if(import.meta.main){const name=process.argv[2],baseline=process.argv.includes('--ci-baseline=m63_integration')?'m63_integration':'m68_qa';try{const fixture=await createM77AuthorDatabase(name,baseline);await Bun.write(`.superpowers/${name}.json`,JSON.stringify(fixture,null,2)+'\n');console.log(JSON.stringify({status:'m77_author_fixture_ready',database:name,fixturePath:`.superpowers/${name}.json`,companyId:fixture.companyId,schemaVersion:20}))}catch(e){console.error(JSON.stringify({status:'m77_author_fixture_failed',code:(e as any)?.code,message:(e as Error).message,where:(e as any)?.where}));process.exitCode=1}}


async function m77BaselineDigests(db:WorkspaceConnection,names?:string[]){const tables=names??(await db.query<{table_name:string}>("select table_name from information_schema.tables where table_schema='neuvetra'and table_type='BASE TABLE'and table_name<>'schema_migrations'order by table_name")).rows.map(r=>r.table_name);const results=[];for(const table of tables){if(!/^[a-z0-9_]+$/.test(table))throw Error('Unexpected baseline table.');const row=(await db.query<{count:number;sha256:string}>(`select count(*)::integer count,encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text)::text,'[]'),'utf8')),'hex')sha256 from neuvetra.${table} x`)).rows[0]!;results.push({table,...row})}return results}

